import sys
NL=chr(10)
s=open(sys.argv[1],encoding='utf-8').read()
snippet='\n/* Touch power: vote the two FT3683 rails while the firmware is still in\n * charge, because the same vote from XNU freezes the user interface a few\n * seconds later. Layout from the live device tree: the apps RSC "drv-2" bank\n * is the third 1 MB reg of rsc@18900000, qcom,tcs-offset 0xd00, distance\n * 0x2a0, three ACTIVE slots first. */\n#define RH_RSC   0x18920000u\n#define RH_CMDB  0x81c60000u\n#define RH_TCS   0xd00u\n#define RH_STRIDE 0x2a0u\n#define RH_WAIT  0x20u\n#define RH_CTL   0x24u\n#define RH_STS   0x28u\n#define RH_EN    0x2cu\n#define RH_MID   0x34u\n#define RH_AD    0x38u\n#define RH_DA    0x3cu\n#define RH_CSTAT 0x40u\n#define RH_CSTRIDE 24u\nstatic unsigned\nrh_rd(unsigned a)\n{\n return *(volatile unsigned *)a;\n}\nstatic void\nrh_wt(unsigned a, unsigned v)\n{\n unsigned i;\n *(volatile unsigned *)a = v;\n for (i = 0; i < 40; i++) {\n  if (rh_rd(a) == v) {\n   return;\n  }\n  BS->stall(50);\n }\n print("rails: reg %#x stuck at %#x want %#x\\n", (uint64_t)a, (uint64_t)rh_rd(a), (uint64_t)v);\n}\nstatic uint64_t\nrh_db16(uint64_t off)\n{\n return (uint64_t)((rh_rd((unsigned)(off & ~3u)) >> (8u * (off & 3u))) & 0xffffu);\n}\nstatic unsigned\nrh_vrm(const char *res)\n{\n uint64_t key[2] = {0, 0};\n uint64_t i, j, addr = 0, hits = 0;\n for (i = 0; i < 8 && res[i]; i++) {\n  key[i / 4] |= (uint64_t)(uint8_t)res[i] << (8u * (i % 4));\n }\n if (rh_rd(RH_CMDB + 4) != 0x0c0330dbu) {\n  print("rails: cmd-db magic %#x\\n", (uint64_t)rh_rd(RH_CMDB + 4));\n  return 0;\n }\n for (i = 0; i < 8; i++) {\n  uint64_t h = 8u + 16u * i, slave = rh_db16(h), entries, count;\n  if (!slave) {\n   break;\n  }\n  entries = 144u + rh_db16(h + 2);\n  count = rh_db16(h + 6);\n  for (j = 0; j < count; j++) {\n   uint64_t e = entries + 24u * j;\n   if ((uint64_t)rh_rd((unsigned)e) != key[0] || (uint64_t)rh_rd((unsigned)(e + 4)) != key[1]) {\n    continue;\n   }\n   addr = rh_rd((unsigned)(e + 16));\n   print("rails: %s addr %#x slave %#x\\n", (uint64_t)res, addr, slave);\n   if (slave == 4 && ((addr >> 16) & 7u) == 4 && !(addr & 15u)) {\n    hits++;\n   }\n  }\n }\n if (hits != 1) {\n  print("rails: %s has %d VRM matches, skipped\\n", (uint64_t)res, hits);\n  return 0;\n }\n return (unsigned)addr;\n}\nstatic void\nrh_vote(unsigned addr, unsigned mv)\n{\n unsigned t, b = 0, bit = 0, irq, c, done = 0;\n for (t = 0; t < 3; t++) {\n  unsigned x = RH_TCS + RH_STRIDE * t;\n  unsigned st = rh_rd(x + RH_STS);\n  if (st != 0 && st != 0xffffffffu && rh_rd(x + RH_CTL) == 0 && rh_rd(x + RH_EN) == 0 &&\n      rh_rd(x + RH_WAIT) == 0 && !(rh_rd(RH_TCS + 4) & (1u << t))) {\n   b = x;\n   bit = 1u << t;\n   break;\n  }\n }\n if (!bit) {\n  print("rails: no free ACTIVE TCS\\n");\n  return;\n }\n irq = rh_rd(RH_TCS + 0);\n rh_wt(RH_TCS + 0, irq & ~bit);\n rh_wt(b + RH_MID, 0x10108u);\n rh_wt(b + RH_AD, addr);\n rh_wt(b + RH_DA, mv);\n rh_wt(b + RH_CSTRIDE + RH_MID, 0x10108u);\n rh_wt(b + RH_CSTRIDE + RH_AD, addr + 8);\n rh_wt(b + RH_CSTRIDE + RH_DA, 7);\n rh_wt(b + 2u * RH_CSTRIDE + RH_MID, 0x10108u);\n rh_wt(b + 2u * RH_CSTRIDE + RH_AD, addr + 4);\n rh_wt(b + 2u * RH_CSTRIDE + RH_DA, 1);\n rh_wt(b + RH_WAIT, 7);\n rh_wt(b + RH_EN, 7);\n rh_wt(b + RH_CTL, 0);\n rh_wt(b + RH_CTL, 1u << 16);\n *(volatile unsigned *)(b + RH_CTL) = (1u << 16) | (1u << 24);\n for (c = 0; c < 2000 && !done; c++) {\n  unsigned k, ok = 1;\n  for (k = 0; k < 3; k++) {\n   unsigned s = rh_rd(b + RH_CSTAT + RH_CSTRIDE * k);\n   ok = ok && s != 0xffffffffu && (s & 0x10100u) == 0x10100u;\n  }\n  done = ok && rh_rd(b + RH_STS) != 0;\n  BS->stall(50);\n }\n print("rails: vote %#x %d mV slot %d done %d\\n", (uint64_t)addr, (uint64_t)mv, (uint64_t)bit, (uint64_t)done);\n rh_wt(b + RH_CTL, 1u << 16);\n rh_wt(b + RH_CTL, 0);\n rh_wt(b + RH_EN, 0);\n rh_wt(b + RH_WAIT, 0);\n *(volatile unsigned *)(RH_TCS + 8) = bit;\n rh_wt(RH_TCS + 0, irq);\n}\nstatic void\nrails_on(void)\n{\n unsigned vddi = rh_vrm("L4B_E0"), avdd = rh_vrm("L16B_E0");\n print("rails: vddi %#x avdd %#x\\n", (uint64_t)vddi, (uint64_t)avdd);\n if (!vddi || !avdd) {\n  return;\n }\n rh_vote(vddi, 1800);\n rh_vote(avdd, 3300);\n}\n'
a1='static void'+NL+'reboot(void)'
a2=' print("platform %s'+chr(92)+'n", PLAT->name);'
for a in (a1,a2):
    if a not in s: raise SystemExit('ANCHOR MISS: '+repr(a[:34]))
s=s.replace(a1, snippet+NL+a1,1)
s=s.replace(a2, a2+NL+' rails_on();',1)
open(sys.argv[1],'w',encoding='utf-8',newline=NL).write(s)
print('loader rails patch applied')
